import numpy as np
from sklearn.ensemble import HistGradientBoostingClassifier

def make_returns(seed, n=1000, kind="threshold"):
    """n daily returns. Volatility moves in slow regimes and the mean
    drifts a little. kind="threshold": when the trailing 20-day vol is
    above 1.2%, a move bigger than 1.5% is followed by a rise of 0.6 sd
    on average, a smaller move by a fall of 0.48 sd. "linear": every day
    reverses 0.3 times yesterday's return. "none": no signal."""
    rng = np.random.default_rng(seed)
    lv, h = np.log(0.01), np.zeros(n)
    h[0] = lv
    for t in range(1, n):
        h[t] = lv + 0.98 * (h[t - 1] - lv) + 0.12 * rng.standard_normal()
    z = rng.standard_normal(n)
    d = np.zeros(n)
    for t in range(1, n):
        d[t] = 0.995 * d[t - 1] + 0.00003 * rng.standard_normal()
    r = np.zeros(n)
    for t in range(n):
        m = 0.0003 + d[t]
        if t >= 20:
            v = r[t - 20:t].std()
            if kind == "threshold" and v > 0.012:
                m += np.exp(h[t]) * (0.6 if abs(r[t - 1]) > 0.015 else -0.48)
            if kind == "linear":
                m += -0.3 * r[t - 1]
        r[t] = m + np.exp(h[t]) * z[t]
    return np.round(r, 6)

def make_study(seed, kind="threshold"):
    """Features for day t: its return, its 20-day vol, three noise columns.
    y = 1 if day t + 1 is up; nxt is day t + 1's return."""
    r = make_returns(seed, kind=kind)
    rows = [[r[t], r[t - 19:t + 1].std()] for t in range(19, len(r) - 1)]
    y = (r[20:] > 0).astype(int)
    noise = np.random.default_rng(seed + 1000).standard_normal((len(y), 3))
    return np.round(np.column_stack([rows, noise]), 6), y, r[20:]

class _Stopped:
    def __init__(self, model, n_trees):
        self.model, self.n_trees = model, n_trees
    def predict_proba(self, X):
        for i, p in enumerate(self.model.staged_predict_proba(X), 1):
            if i == self.n_trees:
                return p

def boost_fit(X, y):
    """Boosting stopped in time order: fit on the first 80% of the rows,
    choose the number of trees (up to 100) on the last 20%."""
    k = int(len(y) * 0.8)
    m = HistGradientBoostingClassifier(max_iter=100, max_depth=2, learning_rate=0.1,
                                       early_stopping=False, random_state=0).fit(X[:k], y[:k])
    yv = y[k:]
    losses = [-np.mean(yv * np.log(np.clip(p[:, 1], 1e-15, 1)) + (1 - yv) * np.log(np.clip(p[:, 0], 1e-15, 1)))
              for p in m.staged_predict_proba(X[k:])]
    return _Stopped(m, int(np.argmin(losses)) + 1)

